using System.Text.Json;
using WypozyczalniaSportowa.Domain.Exceptions;
namespace WypozyczalniaSportowa.Data;

public sealed class JsonStoreRepository(string path) : IStoreRepository { private readonly string _path = path; private static readonly JsonSerializerOptions Options = new() { WriteIndented = true, PropertyNameCaseInsensitive = true }; public StoreSnapshot Load() { if (!File.Exists(_path)) return Empty(); try { using var stream = new FileStream(_path, FileMode.Open, FileAccess.Read, FileShare.Read); var data = JsonSerializer.Deserialize<StoreSnapshot>(stream, Options); if (data is null || data.Equipment is null || data.Customers is null || data.Rentals is null || data.ServiceOrders is null) throw new StoreFormatException("Plik danych nie zawiera wymaganych kolekcji.", new JsonException("Brak kolekcji migawki.")); return data; } catch (JsonException ex) { throw new StoreFormatException("Plik wypożyczalni ma niepoprawny format JSON.", ex); } } public void Save(StoreSnapshot store) { var dir = Path.GetDirectoryName(_path) ?? "."; Directory.CreateDirectory(dir); var temp = _path + ".tmp"; try { using (var stream = new FileStream(temp, FileMode.Create, FileAccess.Write, FileShare.None)) JsonSerializer.Serialize(stream, store, Options); File.Move(temp, _path, true); } catch (IOException) { if (File.Exists(temp)) File.Delete(temp); throw; } } private static StoreSnapshot Empty() => new([], [], [], []); public override string ToString() => "Repozytorium JSON: " + _path; }
